try{(function(){"use strict";if(window.NTLegal)return;var a=Object.assign({name:"NeuroTriage",email:"",address:"",grievance:""},window.NT_LEGAL||{}),i="17 October 2026",t=a.email?'<a href="mailto:'+a.email+'" style="color:inherit">'+a.email+"</a>":"the support email on our app store listing",r={privacy:["Privacy Policy","<p>Effective "+i+". Applies to the "+a.name+" app and website. We follow India's Digital Personal Data Protection Act, 2023.</p><h3>What we collect</h3><ul><li><b>Account:</b> email, name and sign-in provider (Google, Apple or email), only if you create an account.</li><li><b>Health-related entries:</b> screening answers, mood, tasks, thought records and game scores. By default these stay on your device. They are uploaded only if you sign in and use sync/backup.</li><li><b>Payments:</b> handled by Razorpay or Google Play. We never see or store your card, UPI or bank details. We keep only the order ID, plan, amount and dates.</li><li><b>Chat with Amisha:</b> works offline on your device.</li></ul><h3>How we use it</h3><p>To run the app, sync your data, unlock the plan you bought, prevent fraud and answer support requests. We do not sell your data and show no ads. We do not use your health entries for advertising.</p><h3>Who processes it</h3><p>Google Firebase (login and cloud storage), Razorpay (web payments) and Google Play (Play Store payments). They process data only to provide these services.</p><h3>Your rights</h3><ul><li><b>Delete everything:</b> open Account and tap Delete account. Your account, synced data and plan record are erased. Payment records we must keep for tax and accounting law are retained without your health data.</li><li>Access, correct or export your data, withdraw consent, or complain: write to "+t+".</li></ul><h3>Age</h3><p>The app is for people 18 and above. Younger users should use it only with a parent or guardian.</p><h3>Grievance contact</h3><p>"+(a.grievance||"Write to "+t)+(a.address?"<br>"+a.address:"")+"</p>"],terms:["Terms of Use","<p>Effective "+i+". By using "+a.name+" you accept these terms.</p><h3>The service</h3><p>"+a.name+" offers self-help tools, screening questionnaires and focus tools. Free, Pro and Max plans unlock different tools. Features and limits may change; we will not remove what a paid plan promised during its paid period.</p><h3>Plans and payment</h3><ul><li>Prices are shown in Indian rupees (inclusive of applicable taxes) before you pay. All purchases are final; see the Refund page.</li><li><b>Web (Razorpay Autopay):</b> your plan renews automatically every month or every year, as you chose, using UPI Autopay or a card mandate, until you cancel. Each renewal is charged at the amount you agreed to when you subscribed. If we ever change that amount, we will tell you at least 30 days before and you can cancel before it applies.</li><li><b>Before every charge:</b> your bank or UPI app sends a pre-debit notice, as required by RBI rules. You can cancel the mandate any time from the app (Upgrade &gt; Cancel autopay) or from your UPI or bank app. Cancelling stops the next renewal; access continues until the paid period ends.</li><li><b>Google Play:</b> subscriptions renew automatically until cancelled. Cancel anytime in Play Store &gt; Payments &amp; subscriptions. Cancelling stops the next renewal; access continues until the paid period ends.</li><li>Deleting the app or your account does not cancel a Play subscription. Cancel it in Play Store first.</li></ul><h3>Your responsibilities</h3><p>Give honest information, keep your login private and do not misuse, copy or resell the app.</p><h3>Liability</h3><p>The app is provided as is. To the extent allowed by law we are not liable for decisions made only on the basis of in-app results. Indian law applies.</p><p>Questions: "+t+".</p>"],refund:["Refund and Cancellation","<p>Effective "+i+".</p><h3>No refund policy</h3><p>All purchases are final. Once a plan is active, we do not give refunds for change of mind, not using the app, or forgetting to cancel, except as stated below for autopay renewals.</p><h3>Autopay renewals</h3><p>If an autopay renewal was charged and you have not used the paid features since that charge, write to "+t+" within 48 hours. We will cancel autopay and refund that renewal to the original payment method within 5 to 7 working days.</p><h3>What we still fix</h3><ul><li>Charged twice for the same plan, or money was deducted but the plan did not activate: write to "+t+" within 7 days with your payment ID. We will activate the plan or reverse the extra amount to the original payment method within 5 to 7 working days.</li><li>The plan cannot be used because of a fault on our side: we will fix it or extend your plan.</li></ul><h3>Google Play purchases</h3><p>Play purchases follow Google Play's own refund rules, and Google decides those requests (Play Store &gt; Order history &gt; Report a problem).</p><h3>Cancellation</h3><p>Web autopay: tap Upgrade &gt; Cancel autopay in the app, or remove the mandate in your UPI or bank app. The next renewal stops and access continues until the paid period ends.</p><p>Play subscriptions: cancel anytime in Play Store &gt; Payments &amp; subscriptions. Cancelling stops the next renewal; access continues until the paid period ends.</p><h3>Restore</h3><p>Reinstalled or changed phone? Log in with the same account and tap Restore purchase.</p>"],medical:["Medical Disclaimer","<p>"+a.name+' is a self-help and educational tool. Its tests show symptoms and screening scores. They are <b>not a medical diagnosis</b> and do not replace a doctor, psychologist or psychiatrist.</p><h3>If you need help now</h3><ul><li>Tele-MANAS (Govt. of India, free, 24x7): <a href="tel:14416" style="color:inherit"><b>14416</b></a></li><li>KIRAN helpline: <a href="tel:18005990019" style="color:inherit"><b>1800-599-0019</b></a></li><li>Emergency: <a href="tel:112" style="color:inherit"><b>112</b></a></li></ul><p>Never stop or change any medicine because of an app result. Talk to your doctor. SOS, helplines and grounding tools stay free for everyone.</p>']},n="privacy";function c(){var e=document.getElementById("ntLegal");e||(e=document.createElement("div"),e.id="ntLegal",e.setAttribute("role","dialog"),e.setAttribute("aria-modal","true"),e.addEventListener("click",function(o){o.target===e&&l()}),document.body.appendChild(e));var s="";["privacy","terms","refund","medical"].forEach(function(o){s+='<button class="'+(o===n?"on":"")+`" onclick="NTLegal.open('`+o+`')"><span class="ic">`+{privacy:"\u{1F512}",terms:"\u{1F4C4}",refund:"\u{1F4B3}",medical:"\u2695\uFE0F"}[o]+"</span>"+{privacy:"Privacy Policy",terms:"Terms of Use",refund:"Refund Policy",medical:"Medical Disclaimer"}[o]+"</button>"}),e.innerHTML='<div class="lgs" data-k="'+n+'"><button class="x" aria-label="Close" onclick="NTLegal.close()">\u2715</button><h2>'+r[n][0]+'</h2><div class="tb">'+s+"</div>"+r[n][1]+"</div>",e.classList.add("on")}function d(e){n=r[e]?e:"privacy",c()}function l(){var e=document.getElementById("ntLegal");e&&e.classList.remove("on")}window.NTLG=function(){return`<div class="nt-lg"><a href="#" onclick="NTLegal.open('privacy');return false">\u{1F512} Privacy Policy</a><a href="#" onclick="NTLegal.open('terms');return false">\u{1F4C4} Terms of Use</a><a href="#" onclick="NTLegal.open('refund');return false">\u{1F4B3} Refund Policy</a><a href="#" onclick="NTLegal.open('medical');return false">\u2695\uFE0F Medical Disclaimer</a></div>`},window.NTLegal={open:d,close:l,config:a}})()}catch{}
